import type { MemberPlan, RankId } from '../config/plan.ts';

export type PlanCounts = Record<MemberPlan, number>;

export interface Prices {
  /** Activation production generated by one activation of each plan. */
  activation: PlanCounts;
  /** Monthly membership payment of each plan. */
  monthly: PlanCounts;
}

/** One direct Partner team ("leg"). */
export interface Leg {
  id: string;
  label: string;
  /** Rank of the direct Partner who heads this team. */
  rank: RankId;
  /** The direct Partner's own (personal) activations this month — drives Weekly Matching. */
  headActivations: PlanCounts;
  /** Activation volume produced by everyone else in the team this month. */
  otherActivationVolume: number;
  /** Monthly membership payments received from the whole team this month. */
  recurringVolume: number;
}

export interface MonthInput {
  /** Members you personally activated this month (new, upgrades and reactivations). */
  personalActivations: PlanCounts;
  /** Direct members who keep paying their monthly membership. */
  personalPayingMembers: PlanCounts;
  /** Share (0–1) of activations that are first-ever activations (Builders Base Volume). */
  newMemberShare: number;
  /** Quality of Business Index, 0–1. */
  qbi: number;
  /** Share of weeks (0–1) the Weekly Matching Bonus qualifies, or 'auto' to estimate from even weekly production. */
  matchingWeeks: number | 'auto';
  /** Minimum Activations Requirement met through a longer window (90/180/365 days). */
  minActivationsLongWindow: boolean;
  legs: Leg[];
}

export interface CalcProfile {
  isMember: boolean;
  isPartner: boolean;
  memberPlan: MemberPlan;
  /** Partner renewal is paid and current. */
  renewalCurrent: boolean;
  /** This month is the Partner's first full calendar month (Fast Start window). */
  fastStartMonth: boolean;
}

export type IncomeKey = 'dab' | 'mab' | 'matching' | 'tlb' | 'recurring' | 'bbb' | 'fastStart';
export const INCOME_KEYS: IncomeKey[] = ['dab', 'mab', 'matching', 'tlb', 'recurring', 'bbb', 'fastStart'];

/** A translatable explanation: an i18n key with values to interpolate. */
export interface Note {
  key: string;
  params?: Record<string, string | number>;
  tone?: 'info' | 'good' | 'warn';
}

export interface IncomeLine {
  key: IncomeKey;
  amount: number;
  notes: Note[];
}

export interface RankGap {
  rankId: RankId;
  qpRequired: number;
  qpCounted: number;
  legCapAmount: number;
  cappedLegIds: string[];
  tavRequired: number;
  tav: number;
}

export interface MonthResult {
  production: {
    personalActivation: number;
    personalRecurring: number;
    directProduction: number;
    tav: number;
    qp: number;
    rqp: number;
    bbv: number;
  };
  qpRank: RankId;
  paidRank: RankId;
  tlbStatus: 'full' | 'partial' | 'none';
  nextRank: RankGap | null;
  income: Record<IncomeKey, number>;
  lines: IncomeLine[];
  costs: { renewal: number; membership: number; membershipWaiver: number; total: number };
  gross: number;
  net: number;
  conditions: {
    renewalCurrent: boolean;
    minActivations: { required: boolean; met: boolean };
    membershipFree: boolean;
    fastStart: boolean;
    superBbb: boolean;
    eligible: boolean;
  };
  notes: Note[];
}
